// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2023, "2-3", [{"author":"И. Рубанов","question":"Что обычно не нужно делать на уроке?","choices":["писать слова","читать учебник","слушать учителя","считать ворон","решать задачи."],"key":"Г","review":["Что делают на уроке","Проверь, какие действия помогают учиться. Записывать слова, читать учебник, слушать объяснения и решать задачи на уроке могут попросить.","«Считать ворон» обычно говорят про того, кто отвлёкся и смотрит по сторонам. Это лишнее занятие на уроке."]},{"author":"Е. Муравенко","question":"В скольких словах в стихотворении Агнии Барто нужно вместо пропусков вставить букву <em>т</em>?\n<em>Я люблю свою лоша_ку,\nПричешу ей шёрс_ку гла_ко,\nГребешком приглажу хвос_ик\nИ верхом поеду в гос_и.</em>","choices":["в одном","в двух","в трёх","в четырёх","во всех пяти."],"key":"В","review":["Буквы в стихах Барто","Восстанови все слова: «лошадку», «шёрстку», «гладко», «хвостик», «гости». В проверочных словах «лошадей» и «гладенький» после буквы Д стоит гласная, поэтому слышно [д’].","Буква Т нужна в «шёрстку», «хвостик» и «гости». Таких слов три."]},{"author":"А. Ковалёва","question":"Как <strong>не</strong> называли медведя в русских сказках?","choices":["<em>Михайло</em> <em>Иванович</em>","<em>Топтыгин</em>","<em>Мишутка</em>","<em>Горыныч</em>","<em>Косолапый</em>."],"key":"Г","review":["Медведь в сказках","Вспомни, как в сказках называют медведя: Михайло Иванович, Топтыгин, Мишутка и Косолапый.","В имени «Горыныч» слышится знакомое прозвище Змея. Оно принадлежит другому сказочному герою."]},{"author":"Е. Муравенко","question":"Даны слова <em>бок</em>, <em>дом</em>, <em>клок</em>, <em>крошка</em>, <em>мошка</em>. В скольких словах можно букву <em>о</em> заменить буквой <em>ы</em>, чтобы получилось новое слово?","choices":["во всех пяти","в четырёх","в трёх","в двух","в одном."],"key":"А","review":["Из О получается Ы","Замени О на Ы в каждом слове, сохранив остальные буквы. Из «бок» получится «бык», из «дом» — «дым», из «клок» — «клык».","«Крошка» даёт «крышка», а «мошка» — «мышка». Во всех пяти случаях получилось новое слово."]},{"author":"А. Ковалёва","question":"В какой паре слов <strong>нет</strong> противопоставления?","choices":["<em>высокий — рослый</em>","<em>горячий — холодный</em>","<em>сладкий — горький</em>","<em>длинный — короткий</em>","<em>толстый — худой.</em>"],"key":"А","review":["Сходство и противоположность","Сравни признаки внутри каждой пары. «Горячий» и «холодный» отличаются по температуре, «длинный» и «короткий» — по длине, «толстый» и «худой» — по телосложению. «Сладкий» и «горький» противопоставлены по вкусу.","«Рослый» значит «высокий ростом». Про одного человека можно сказать и «рослый», и «высокий», поэтому противопоставления в этой паре нет."]},{"author":"И. Рубанов","question":"<em>Впереди виднелась земля. Колумб дрожащими руками схватил _____ трубу</em> (И. Ильф, Е. Петров. Колумб причаливает к берегу). Какую трубу схватил Колумб?","choices":["<em>зазорную</em>","<em>обзорную</em>","<em>подзорную</em>","<em>подозрительную</em>","<em>пароходную</em>."],"key":"В","review":["Труба Колумба","Колумб заметил землю вдали. Чтобы лучше разглядеть берег, ему понадобился прибор, через который удобно смотреть на отдалённые предметы.","Такой прибор называется подзорной трубой. По смыслу подходит «схватил подзорную трубу», чтобы рассмотреть землю."]},{"author":"Е. Муравенко","question":"Что зашифровано в этом ребусе?","choices":["название дерева","название цветка","название зверя","название птицы","название насекомого."],"key":"Б","review":["Две картинки в ребусе","На первом рисунке рот. Зачёркнутая Т подсказывает, что её надо убрать. Остаётся «ро».","На втором рисунке марка. Стрелка меняет Р на Ш, выходит «машка». Соедини «ро» и «машка» и получишь «ромашка» — название цветка."],"figure":{"condition":{"src":"assets/medvezhonok/2023/2-3-7.webp","width":497,"height":249,"pixelWidth":497,"pixelHeight":249,"alt":"Над ртом зачёркнута Т, над почтовой маркой указана замена Р на Ш."}}},{"author":"О. Подлесская","question":"В стихотворении Галины Дядиной пропущен конец первой строчки. Восстановите его.\n<em>Мы с тобой идём __________\nИ не просто так совсем!\nМы с тобой соединились\nВот в такую букву «М»!</em>","choices":["<em>в обнимку</em>","<em>за ручку</em>","<em>вприпрыжку</em>","<em>под ручку</em>","<em>вразвалку</em>."],"key":"Б","review":["Прогулка буквой М","Посмотри на букву М. У неё две вертикальные линии по краям и две наклонные, которые сходятся посередине.","Если двое идут рядом и держатся за ручку, тела станут внешними линиями, а две руки сойдутся посередине. Получится буква М."]},{"author":"Б. Иомдин","question":"<em>— Яша, разбери рюкзак!</em>\n<em>— Всё, рюкзак _____.</em>\nКак правильно сказать?","choices":["<em><u>разберён</u></em>","<em><u>разобрён</u></em>","<em><u>разобран</u></em>","<em><u>раз</u></em><em>обрат</em>","<em>разбран</em>."],"key":"В","review":["Яшин рюкзак","Вспомни такие же пары слов: «собрать — собран», «убрать — убран». Так описывают уже законченные действия.","Для «разобрать» нужна форма «разобран». Проверь её в полной фразе: «Всё, рюкзак разобран»."]},{"author":"Л. Фёдорова","question":"<em>Плывут\nКучевые болонки\nНад нами,\nА дым из трубы\nПоднялся пудельками,\nДве перистых колли\nСидят на сосне…\nЯ лапкою дёрнул\nИ тявкнул\nВо сне.</em>\nКак называется это стихотворение Михаила Яснова?","choices":["«Кошкин сон»","«Щенячий сон»","«Сон козлёнка»","«Сон утёнка»","«Сон вороны»."],"key":"Б","review":["Кому снится этот сон","Найди в строках знакомые названия пород: болонки, пудели и колли. Все три — собаки, которых герой увидел в облаках и дыме.","Тот, кому снится сон, говорит «тявкнул». Так лает щенок, поэтому стихотворение называется «Щенячий сон»."]},{"author":"А. Ковалёва","question":"Даны пары существительных во множественном числе. В какой паре оба слова можно употребить в единственном числе?","choices":["<em>руки — брюки</em>","<em>шорты — торты</em>","<em>сапоги — пироги</em>","<em>носилки — копилки</em>","<em>пятки — прятки</em>."],"key":"В","review":["Из многих в один","Попробуй назвать по одному предмету каждого вида. Получатся «рука», «торт», «копилка» и «пятка», а вот «брюки», «шорты», «носилки» и «прятки» употребляются только во множественном числе.","В паре «сапоги — пироги» обе формы получаются: один сапог и один пирог. Это единственная подходящая пара."]},{"author":"О. Подлесская","question":"Разгадайте загадку: <em>Ношу на голове поля, но это вовсе не земля</em>.","choices":["<em>шапка</em>","<em>кепка</em>","<em>фуражка</em>","<em>косынка</em>","<em>шляпа</em>."],"key":"Д","review":["Поля на голове","Слово «поля» бывает названием края, который окружает головной убор. Посмотри, где такой край идёт вокруг всей головы.","У шляпы есть поля, у кепки и фуражки — козырёк спереди. Загадка про шляпу."]},{"author":"Е. Муравенко","question":"Сколько названий месяцев содержат букву <em>а</em>?","choices":["6","7","8","9","10."],"key":"Б","review":["Буква в названиях месяцев","Выпиши месяцы по порядку и обведи А. В первой половине года А есть в январе, феврале, марте, апреле и мае.","Во второй половине подходят август и декабрь. Всего 5 + 2 = 7 названий содержат А."]},{"author":"А. Пиперски","question":"Какая форма слова <em>медвежонок</em> неправильная?","choices":["<em>медвежонка</em>","<em>медвежонку</em>","<em>медвежонком</em>","<em>медвежонке</em>","<em>медвежонки</em>."],"key":"Д","review":["Формы слова «медвежонок»","Подставь формы к вопросам: нет кого? медвежонка. Дали кому? медвежонку. Гуляли с кем? с медвежонком. Говорили о ком? о медвежонке.","Для нескольких детёнышей есть форма «медвежата». Поэтому «медвежонки» — неправильный вариант."]},{"author":"О. Подлесская","question":"Сеня расстроился, что его младшая сестра Нина плохо себя вела в гостях. Он извинился __________.","choices":["перед ней","за неё","про неё","из неё","за ней."],"key":"Б","review":["Сеня в гостях","Сеня был недоволен поведением Нины. В этой ситуации хозяева могут услышать извинение, а причина извинения — поступок сестры.","Если извиняешься за поступок другого человека, говорят «извиниться за него». Сеня извинился за неё. Перед ней он бы извинился, если бы сам её обидел."]},{"author":"Е. Муравенко","question":"Какое слово можно получить, если взять из каждого слова — <em>корова</em>, <em>победа</em>, <em>пригорок</em> — по одному слогу?","choices":["<em>порода</em>","<em>погода</em>","<em>подарок</em>","<em>корона</em>","<em>природа</em>."],"key":"Д","review":["По слогу из трёх слов","Раздели слова на слоги: «ко-ро-ва», «по-бе-да», «при-го-рок». Для нового слова нужно использовать по одному слогу каждого.","Соедини «при» из «пригорок», «ро» из «корова» и «да» из «победа». Получится «при-ро-да», причём все три исходных слова использованы."]},{"author":"Л. Фёдорова","question":"Когда мальчики ходили в детский сад, их называли Антон, Володя, Костя, Саша, Федя. Когда они пошли записываться в первый класс, их спросили полные имена. Чьё имя оказалось самым длинным?","choices":["Антона","Володи","Кости","Саши","Феди."],"key":"В","review":["Полные имена мальчиков","Запиши полные имена: Антон, Владимир, Константин, Александр и Фёдор. Для сравнения считай буквы в полных именах.","У Константина 10 букв, у Александра 9, а остальные ещё короче. Самое длинное имя у Кости."]},{"author":"А. Пиперски и Е. Бикмаев","question":"Что из этого бывает?","choices":["<em>торжественный циркуль</em>","<em>торжественный пенал</em>","<em>торжественный карандаш</em>","<em>торжественный треугольник</em>","<em>торжественная линейка</em>."],"key":"Д","review":["Торжественный школьный день","Подумай, какие из перечисленных слов могут обозначать школьное событие. Циркуль, пенал, карандаш и треугольник здесь названия предметов.","Линейкой называют и школьное построение. Такое событие, например в первый учебный день, может быть торжественным."]},{"author":"Л. Фёдорова","question":"В «Сказке без конца и начала» Андрея Усачёва рассыпались первые фразы.\n1. И зачем я живу на свете?»\n2. Поглядел, как волны одна за другой на берег накатываются, и загрустил:\n3. Приполз Муравей на берег моря.\n4. Сел Муравей под пальму и заплакал — так ему стало обидно.\n5. «Море такое большое, а я такой маленький… За всю свою жизнь я не смогу увидеть его конца.\nПомогите их собрать в правильном порядке.","choices":["1, 2, 3, 4, 5","4, 1, 3, 5, 2","3, 4, 1, 2, 5","4, 5, 1, 3, 2","3, 2, 5, 1, 4."],"key":"Д","review":["Муравей у моря","Сначала Муравей приполз на берег (3), потом увидел волны и загрустил (2). Двоеточие после второй фразы предупреждает, что дальше будут его мысли.","Кавычки открываются в (5) и закрываются в (1). После этих мыслей он сел и заплакал (4). Порядок — 3, 2, 5, 1, 4."]},{"author":"Л. Фёдорова","question":"В книге Марии Крюгер «Голубая бусинка» оживший каменный лев «с наслаждением потянулся и промурлыкал:\n— Ох! И затерпли же у меня лапы!»\nЛев использовал довольно редкое слово. Чем можно его заменить?","choices":["<em>затерпели</em>","<em>затёрлись</em>","<em>затрепались</em>","<em>затекли</em>","<em>затрепетали</em>."],"key":"Г","review":["Лапы каменного льва","Каменный лев долго не двигался, а ожив, сразу потянулся. Вспомни, что бывает с рукой или ногой, если долго держать её неподвижно.","Такая рука или нога затекает и временно плохо чувствуется. «Затерпли лапы» означает «затекли лапы»."]},{"author":"И. Иткин и Л. Иткин","question":"Назовём слова <em>мышь, листок, правило</em> разнобуквицами. А какое из этих слов — <strong>не</strong> разнобуквица?","choices":["<em>поезд</em>","<em>столешница</em>","<em>разнобуквица</em>","<em>четырёхугольник</em>","все эти слова — разнобуквицы."],"key":"В","review":["Разнобуквицы","Отметь по одной каждую букву в словах «мышь», «листок», «правило». В каждом все буквы разные. Значит, ищем вариант, в котором буква повторена.","В слове «разнобуквица» буква А встречается дважды, а в словах «поезд», «столешница» и «четырёхугольник» буквенных повторов нет."]},{"author":"И. Рубанов","question":"Мама: «Не могу найти _____!» Папа: «Сына или украшение?» Как зовут сына?","choices":["Борис","Георгий","Николай","Олег","Сергей."],"key":"Д","review":["Сын или украшение","В пропуске должно прозвучать слово, которым можно назвать и мальчика, и небольшое украшение. Вспомни, как по-домашнему называют Сергея.","Сергей — Серёжа или Серёжка. Фраза «не могу найти Серёжку» звучит так же, как «не могу найти серёжку», поэтому папа переспросил."]},{"author":"Л. Фёдорова","question":"Гриша постоянно приходил в школу с невыученными уроками. Учитель сказал Грише, что <em>пора</em> <em>взяться за</em> _____. Закончите предложение.","choices":["<em>голову</em>","<em>уши</em>","<em>ум</em>","<em>руки</em>","<em>старое</em>."],"key":"В","review":["Совет Грише","Гриша всё время приходит с невыученными уроками. Учитель советует ему образумиться и серьёзно отнестись к учёбе.","В таком случае говорят «взяться за ум». Слово «ум» завершает устойчивое выражение."]},{"author":"А. Ковалёва","question":"В слове <em>листок</em> скрывается число <em>сто</em>. Сколько чисел скрывается в этом тексте?\n<em>Весной в подвале нашего дома нашли нескольких почти одинаковых котят. Кошка никого не подпускала к своей семье. «Посмотри, Петя, она, наверное, проголодалась, — сказала Люся, — давай опять придём сюда и принесём ей еды».</em>","choices":["одно","два","три","четыре","пять."],"key":"Д","review":["Числа внутри слов","Ищи подряд идущие буквы, как «сто» в слове «листок». В тексте уже можно отметить «два» в «подвале» и «один» в «одинаковых».","Ещё есть «семь» в «семье», «три» в «посмотри» и «пять» в «опять». С двумя первыми получается пять чисел."]},{"author":"И. Рубанов","question":"Игорь собирает слова с одним довольно редким свойством. В его коллекции есть слова <em>дед</em>, <em>кот</em>, <em>нос</em>, <em>зов</em>. Какое слово может быть там ещё?","choices":["<em>кум</em>","<em>мука</em>","<em>полк</em>","<em>сом</em>","<em>шум</em>."],"key":"В","review":["Коллекция Игоря","Прочитай примеры с конца. «Дед» останется «дед», «кот» станет «ток», «нос» — «сон», а «зов» — «воз». Получаются обычные слова в начальной форме.","Из «полк» получается «клоп». Если перевернуть «кум», выйдет «мук», как в выражении «много мук». Это форма слова «му́ка», а в коллекции при чтении в обе стороны выходят слова в начальной форме."]},{"author":"Л. Фёдорова","question":"В названии лесного зверька две буквы, но три звука. А если добавить ещё один звук, получится название рыбки. Какой же звук надо добавить?","choices":["[б]","[л]","[р]","[с]","[т]."],"key":"В","review":["Зверёк превращается в рыбку","Зверёк из двух букв — ёж. В начале слова Ё передаёт [й’] и [о]. Буква Ж на конце звучит как [ш].","Вставь [р] после [о]: из [й’ош] получится [й’орш]. Получилась рыба ёрш."]},{"author":"О. Подлесская","question":"В каком отрывке слово <em>вдруг</em> значит не то же, что в остальных?","choices":["<em>Вдруг подул сильный ветер, и деревья закачались</em>.","<em>Вдруг пойдёт дождь, не забудь захватить зонтик</em>.","<em>Вдруг появляется главный герой и спасает всех от злодеев</em>.","<em>Вдруг раздался звонок в дверь, мы побежали открывать</em>.","<em>Вдруг все забегали, закричали друг на друга, затопали ногами</em>."],"key":"Б","review":["Два смысла слова «вдруг»","В четырёх отрывках «вдруг» можно заменить на «внезапно»: ветер подул, герой появился, звонок раздался, все забегали.","Дождь ещё не пошёл, но может пойти. Здесь «вдруг» значит «а если»: «А если пойдёт дождь, захвати зонтик»."]},{"author":"К. Кноп","question":"Вставьте два пропущенных слова так, чтобы получилось верное утверждение.\n«В этом предложении буква <strong>р</strong> встречается _____ раз, буква <strong>т</strong> — _____ раз».","choices":["пять, четыре","шесть, шесть","пять, пять","пять, шесть","шесть, пять."],"key":"Г","review":["Сосчитай буквы в утверждении","Без пропусков Р встречается пять раз: в «предложении», отдельно, во «встречается» и в двух «раз». Т встречается четырежды: в «этом», дважды во «встречается» и отдельно.","Слова «пять» и «шесть» не добавляют Р, а букву Т добавляют по одной. Получается пять Р и шесть Т, как и сказано в предложении."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
